public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Initialize the graph and partition the vertices based on the input map
    target.setDirected(false);
    Set<String> partition = new HashSet<>(resultMap.keySet());
    Set<V> leftVertices = new HashSet<>(partition.size());
    Set<V> rightVertices = new HashSet<>(partition.size());

    // Add the vertices to the graph
    for (String key : resultMap.keySet()) {
        V vertex = resultMap.get(key);
        leftVertices.add(vertex);
        rightVertices.add(vertex);
    }

    // Generate edges between each possible pair of vertices
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            if (!leftVertex.equals(rightVertex)) {
                Edge<V, E> edge = target.addEdge(leftVertex, rightVertex);
                target.setEdgeWeight(edge, 1.0);
            }
        }
    }
}

