        rightVertexSet.add(target.getVertices().get(i));
    }
    for (int i = 0; i < leftVertexSet.size(); i++) {
        for (int j = 0; j < rightVertexSet.size(); j++) {
            if (i != j) {
                E edge = new E();
                edge.setLeftVertex(leftVertexSet.get(i));
