        }
    }
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create a bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<>();

    // Add nodes and edges to the bipartite graph
    for (V node : target.getNodes()) {
        // Add node to bipartite graph with same label as target node
        bipartiteGraph.addNode(node.getLabel(), node.getProperties());

        for (E edge : target.getEdges(node)) {
            // Add edge to bipartite graph with same label as target edge
            bipartiteGraph.addEdge(
                edge.getLabel(),
                bipartiteGraph.getNode(node.getLabel()),
                bipartiteGraph.getNode(edge.getTarget().getLabel()),
                edge.getProperties()
            );
        }
    }

    resultMap.put("bipartiteGraph", bipartiteGraph);
}

