    // step 1: create the two sets of vertices
    List<V> set1 = new ArrayList<>(resultMap.values());
    List<V> set2 = new ArrayList<>();
    for (V v : set1) {
        if (!resultMap.containsKey(v.getNeighbors())) {
            set2.add(v);
