    for (int i = 0; i < set1.size(); i++) {
        for (int j = 0; j < set2.size(); j++) {
            E edge = new E();
            edge.setVertex1(set1.get(i));
            edge.setVertex2(set2.get(j));
            target.addEdge(edge);
        }
    }

    // step 3: add the vertices from set2 to the graph
    for (V v : set2) {
        target.addVertex(v);
    }
}

