protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize an empty list to hold the vertices in the graph path
    List<V> vertices = new ArrayList<>();

    // Iterate over the set of edges in the tour
    for (E edge : tour) {
        // Get the vertices associated with the current edge
        V startVertex = graph.getEdgeStart(edge);
        V endVertex = graph.getEdgeEnd(edge);

        // Add the vertices to the list, in the order they appear in the tour
        vertices.add(startVertex);
        vertices.add(endVertex);
    }

    // Create a graph path from the list of vertices
    GraphPath<V,E> path = new GraphPath<>(graph, vertices);

    // Return the graph path
    return path;
}

public static GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }

    List<V> vertices = new ArrayList<>();
    for (E edge : tour) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }

    return new GraphPathImpl<>(graph, vertices);
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>();
    for (E edge : tour) {
        path.add(edge);
        V src = graph.get(edge);
        V dest = graph.get(edge);
        path.connect(src, dest);
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize an empty graph path
    GraphPath<V, E> path = new GraphPathImpl<V, E>();

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Add the edge to the path
        path.addEdge(edge);

        // If the edge is a self loop, skip the next edge
        if (edge.equals(edge.getOpposite(edge.getStart()))) {
            continue;
        }

        // Get the next edge in the tour
        E nextEdge = graph.getEdge(edge.getOpposite(edge.getEnd()));

        // Add the next edge to the path
        path.addEdge(nextEdge);

        // If the next edge is also a self loop, skip it
        if (nextEdge.equals(nextEdge.getOpposite(nextEdge.getStart()))) {
            path.removeLastEdge();
        }
    }

    // Return the completed graph path
    return path;
}

