        if (!graph.adjacentVertices(v).containsAll(vertices)) {
            return false;
        }
    }
    // check if the complete subgraph is a clique
    for (V v : completeSubgraph) {
        if (!isClique(graph, completeSubgraph, v)) {
            return false;
        }
    }
    return true;
}

