    // check if all neighbors of v are in the complete subgraph
    for (V w : graph.adjacentVertices(v)) {
        if (!completeSubgraph.contains(w)) {
            return false;
        }
    }
    // check if v is a clique
    Set<V> clique = new HashSet<>(completeSubgraph);
    clique.add(v);
    return Graphs.isCycle(graph, clique);
}

