  List<SequenceRange> sequenceRanges = new ArrayList<>();

  // Proposal 1: current profiles segment snapshot search sequence range
  // 1.1: current profiles segment
  Profile currentProfile = new Profile();
  currentProfile.setCurrent(true);
  // 1.2: snapshot
  Snapshot currentSnapshot = new Snapshot();
  currentSnapshot.setProfile(currentProfile);
  // 1.3: search sequence range
  SearchSequenceRange currentSearchSequenceRange = new SearchSequenceRange();
  currentSearchSequenceRange.setSnapshot(currentSnapshot);

  // Proposal 2: current profiles segment snapshot search sequence range
  // 2.1: current profiles segment
  Profile nextProfile = new Profile();
  nextProfile.setCurrent(false);
  nextProfile.setPreviousProfile(currentProfile);
  currentProfile.setNextProfile(nextProfile);
  // 2.2: snapshot
  Snapshot nextSnapshot = new Snapshot();
  nextSnapshot.setProfile(nextProfile);
  // 2.3: search sequence range
  SearchSequenceRange nextSearchSequenceRange = new SearchSequenceRange();
  nextSearchSequenceRange.setSnapshot(nextSnapshot);

  // add both proposals to the list of sequence ranges
  sequenceRanges.add(currentSearchSequenceRange);
  sequenceRanges.add(nextSearchSequenceRange);

  // return the list of sequence ranges
  return sequenceRanges;
}

