    // Get the current profiles segment snapshot
    List<Profile> profiles = getCurrentProfilesSnapshot();

    // Create a new list to store the sequence ranges
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Iterate over the profiles
    for (Profile profile : profiles) {
        // Get the profile's search sequence
        String searchSequence = profile.getSearchSequence();

        // If the search sequence is not empty, add it to the sequence ranges list
        if (!searchSequence.isEmpty()) {
            sequenceRanges.add(new SequenceRange(searchSequence));
        }
    }

    // Return the sequence ranges list
    return sequenceRanges;
