            sequenceRanges.add(new SequenceRange(searchSequence));
        }
    }

    // Return the sequence ranges list
    return sequenceRanges;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<SequenceRange>();

    // Generate the current profiles segment snapshot
    for (Profile profile : currentProfiles) {
        SequenceRange sequenceRange = new SequenceRange();
        sequenceRange.setProfile(profile);
        sequenceRange.setSnapshot(profile.getSnapshot());
        sequenceRanges.add(sequenceRange);
    }

    // Search the sequence ranges for intersection
    for (SequenceRange sequenceRange : sequenceRanges) {
        for (SequenceRange otherSequenceRange : sequenceRanges) {
            if (sequenceRange.getProfile() == otherSequenceRange.getProfile() &&
                    sequenceRange.getStart() < otherSequenceRange.getEnd() &&
                    otherSequenceRange.getStart() < sequenceRange.getEnd()) {
                sequenceRange.setEnd(Math.min(sequenceRange.getEnd(), otherSequenceRange.getEnd()));
            }
        }
    }

    return sequenceRanges;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Get current profile data
    Profile[] profiles = getCurrentProfiles();

    // Iterate over profiles
    for (Profile profile : profiles) {
        // Get all segments for the current profile
        Segment[] segments = profile.getSegments();

        // Iterate over segments
        for (Segment segment : segments) {
            // Get all snapshot IDs for the current segment
            int[] snapshotIds = segment.getSnapshotIds();

            // Iterate over snapshot IDs
            for (int snapshotId : snapshotIds) {
                // Add a new sequence range for the current snapshot ID
                sequenceRanges.add(new SequenceRange(snapshotId, snapshotId));
            }
        }
    }

    return sequenceRanges;
}

