public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 11) {
        return desiredCapacity;
    }

    // Calculate the next prime number by iterating through all odd numbers starting from 11
    for (int i = 11; i < desiredCapacity; i += 2) {
        if ((i & 1) != 0) {
            int j = 3;
            while (j <= Math.sqrt(i)) {
                if (i % j == 0) {
                    break;
                }
                j += 2;
            }
            if (j > Math.sqrt(i)) {
                return i;
            }
        }
    }

    // if the loop completes, the desired capacity was not found
    return desiredCapacity;
}

public static int nextPrime(int desiredCapacity) {
    // Handle the case where the desired capacity is 0 or negative
    if (desiredCapacity <= 0) {
        return 1;
    }

    // Handle the case where the desired capacity is 1 or 2
    if (desiredCapacity <= 2) {
        return desiredCapacity;
    }

    // Otherwise, round up the desired capacity to the next largest multiple of 2
    int roundedDesiredCapacity = (desiredCapacity + 1) & (~1);

    // Check if the rounded capacity is prime
    boolean isPrime = true;
    for (int i = 2; i < roundedDesiredCapacity; i++) {
        if (roundedDesiredCapacity % i == 0) {
            isPrime = false;
            break;
        }
    }

    if (isPrime) {
        return roundedDesiredCapacity;
    } else {
        // If the rounded capacity is not prime, find the next prime number greater than it
        for (int i = roundedDesiredCapacity + 1; i < Integer.MAX_VALUE; i++) {
            if (i % 2 != 0 && i % 3 != 0 && i % 5 != 0 && i % 7 != 0) {
                return i;
            }
        }
    }

    return -1;
}

public static int nextPrime(int desiredCapacity) {
    int prime = 1;
    if (desiredCapacity < 11) {
        return 11;
    }

    if (desiredCapacity < 101) {
        prime = 11;
    } else {
        prime = 101;
    }

    while (prime < desiredCapacity * 1.1) {
        prime += 2;
    }

    return prime;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity >= 1000) {
        return Math.round((float) desiredCapacity + (float) (desiredCapacity * 0.11));
    } else {
        return Math.round((float) desiredCapacity + (float) (desiredCapacity * 0.1f));
    }
}

private static int nextPrime(int desiredCapacity) {
    // If the desired capacity is less than 1000, the prime number is within 11%
    if (desiredCapacity < 1000) {
        return (int) (desiredCapacity * 1.1);
    }

    // If the desired capacity is greater or equal to 1000, the prime number is within 11% + 1
    return (int) (desiredCapacity * 1.11);
}

