public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int strLen = str.length();
    int charPos = 0;

    while (charPos < strLen) {
        int start = charPos;
        int c = str.charAt(charPos++);
        if (c >= 0xD800 && c <= 0xDBFF) {
            if (charPos < strLen) {
                c = (c << 10) + str.charAt(charPos++);
                c = c - 0x35FDC00;
            } else {
                throw new UTFDataFormatException();
            }
        }
        if (c < 0x80) {
            lb.add(c);
        } else if (c < 0x800) {
            lb.add(0xC0 | c >> 6);
            lb.add(0x80 | c & 0x3F);
        } else if (c < 0xD800 || c > 0xDFFF) {
            lb.add(0xE0 | c >> 12);
            lb.add(0x80 | c >> 6 & 0x3F);
            lb.add(0x80 | c & 0x3F);
        } else {
            if (c == 0xD800) {
                throw new UTFDataFormatException();
            }
            lb.add(0xED | c >> 12);
            lb.add(0x80 | c >> 6 & 0x3F);
            lb.add(0x80 | c & 0x3F);
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    final CodingErrorAction codingErrorAction = session.getCodingErrorAction();
    if (codingErrorAction.equals(CodingErrorAction.REPORT)) {
        lb.writeUTF8(str);
    } else {
        lb.writeUtil.writeString(str, codingErrorAction);
    }
    return lb;
}

